  const _tedxScrubFill  = tedxScrubber.querySelector('#__tedxScrubFill');
  const _tedxScrubKnob  = tedxScrubber.querySelector('#__tedxScrubKnob');
  const _tedxScrubCur   = tedxScrubber.querySelector('#__tedxScrubCur');
