    lab.style.cssText = 'font-weight:700;font-size:11px;color:#000;letter-spacing:0.06em;';
    const val = document.createElement('span');
    val.style.cssText = 'color:#000;font:11px ui-monospace,Menlo,monospace;background:#f0f0f0;padding:2px 6px;border-radius:4px;border:1px solid #999;min-width:60px;text-align:right;';
    top.appendChild(lab); top.appendChild(val);
    const sliderRow = document.createElement('div');
    sliderRow.style.cssText = 'display:flex;align-items:center;gap:5px;';
    const slider = document.createElement('input');
    slider.type = 'range';
