    slider.value = String((window.__pixarBox || {})[key] ?? opts.def);
    slider.style.cssText = 'flex:1;height:20px;accent-color:#000;cursor:pointer;background:#fff;';
    sliderRow.appendChild(slider);
    function _mkBtn(txt, delta) {
      const b = document.createElement('button');
      b.textContent = txt;
      b.style.cssText = 'min-width:26px;height:22px;border:1px solid #111;background:#fff;color:#000;border-radius:5px;cursor:pointer;font:700 11px system-ui;padding:0 4px;';
      b.addEventListener('mouseenter', () => { b.style.background = '#000'; b.style.color = '#fff'; });
      b.addEventListener('mouseleave', () => { b.style.background = '#fff'; b.style.color = '#000'; });
      b.addEventListener('click', () => {
        const cur = parseFloat(slider.value);
        const next = _applyPixarBoxVal(key, cur + delta, opts);
        slider.value = String(next);
        paint();
      });
      return b;
    }
    sliderRow.appendChild(_mkBtn('−', -opts.fine));
    sliderRow.appendChild(_mkBtn('+', +opts.fine));
    const paint = () => { val.textContent = Number(slider.value).toFixed(3); };
