  _pixarBoxRows.appendChild(_rLab);
  _pixarBoxRows.appendChild(_mkPixarBoxRow('Rot X', 'rotX', { min: -Math.PI, max: Math.PI, step: 0.01, fine: 0.05, def: 0, persist: 'pixar.box.rotX' }));
  _pixarBoxRows.appendChild(_mkPixarBoxRow('Rot Y', 'rotY', { min: -Math.PI, max: Math.PI, step: 0.01, fine: 0.05, def: 0, persist: 'pixar.box.rotY' }));
  _pixarBoxRows.appendChild(_mkPixarBoxRow('Rot Z', 'rotZ', { min: -Math.PI, max: Math.PI, step: 0.01, fine: 0.05, def: 0, persist: 'pixar.box.rotZ' }));
  // Top flap hinges — Math.PI ≈ 3.14, so the slider's [-1.6, 2.5]
  // covers fully closed (negative) through past 90° open.
  const _hDiv = document.createElement('div');
  _hDiv.style.cssText = 'height:1px;background:#222;margin:6px 0 4px 0;';
  _pixarBoxRows.appendChild(_hDiv);
  const _hLab = document.createElement('div');
  _hLab.textContent = 'TOP FLAPS (radians)';
  _hLab.style.cssText = 'font-size:9px;letter-spacing:0.2em;color:#000;font-weight:700;margin-bottom:2px;';
  _pixarBoxRows.appendChild(_hLab);
  _pixarBoxRows.appendChild(_mkPixarBoxRow('Lid (front)',  'lid',       { min: -1.6, max: 2.5, step: 0.01,  fine: 0.05, def: 0,   persist: 'pixar.box.lid' }));
  _pixarBoxRows.appendChild(_mkPixarBoxRow('Back flap',    'flapBack',  { min: -1.6, max: 2.5, step: 0.01,  fine: 0.05, def: 0,   persist: 'pixar.box.flapBack' }));
  _pixarBoxRows.appendChild(_mkPixarBoxRow('Left flap',    'flapLeft',  { min: -1.6, max: 2.5, step: 0.01,  fine: 0.05, def: 0,   persist: 'pixar.box.flapLeft' }));
  _pixarBoxRows.appendChild(_mkPixarBoxRow('Right flap',   'flapRight', { min: -1.6, max: 2.5, step: 0.01,  fine: 0.05, def: 0,   persist: 'pixar.box.flapRight' }));
  // ── BALL section: independent scale of the Luxo ball inside the box.
  const _ballDiv = document.createElement('div');
  _ballDiv.style.cssText = 'height:1px;background:#bbb;margin:8px 0 4px;';
  _pixarBoxRows.appendChild(_ballDiv);
  const _ballLab = document.createElement('div');
  _ballLab.textContent = 'LUXO BALL';
  _ballLab.style.cssText = 'font-size:9px;letter-spacing:0.2em;color:#000;font-weight:700;margin-bottom:2px;';
  _pixarBoxRows.appendChild(_ballLab);
