  _tedxTvRows.appendChild(_mkTvRow('X',     'x',     { min: -3,   max: 3,   step: 0.005, fine: 0.01,  coarse: 0.1,  persist: 'tedx.tv.x' }));
  _tedxTvRows.appendChild(_mkTvRow('Y',     'y',     { min: -3,   max: 3,   step: 0.005, fine: 0.01,  coarse: 0.1,  persist: 'tedx.tv.y' }));
