    _lockPivotBtn.style.cssText = `margin-top:6px;width:100%;padding:7px;border-radius:6px;border:1.5px solid #111;background:${on ? '#ffe17a' : '#fff'};color:#111;cursor:pointer;font:700 11px system-ui;`;
