  const tvBtnRow = document.createElement('div');
  tvBtnRow.style.cssText = `
    position: fixed; display: none; z-index: 60;
    gap: 8px; align-items: center;
    pointer-events: auto;
    padding: 6px 10px; border-radius: 12px;
    background: rgba(0,0,0,0.25);
    border: 1px solid rgba(255,255,255,0.06);
    backdrop-filter: blur(4px);
  `;
  function mkTvBtn(label, content, onClick) {
    const b = document.createElement('button');
    b.title = label;
    b.innerHTML = content;
    b.dataset.label = label;
    b.style.cssText = `
      width: 48px; height: 48px; border-radius: 10px;
      background: rgba(28,16,16,0.78);
      border: 1px solid rgba(255,255,255,0.10);
      color: #ff5544; cursor: pointer;
      display: flex; align-items: center; justify-content: center;
      box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), 0 2px 8px rgba(0,0,0,0.6);
      transition: transform 0.15s, background 0.15s, box-shadow 0.15s, border-color 0.15s;
    `;
    b.addEventListener('mouseenter', () => {
      b.style.transform = 'scale(1.16)';
      b.style.background = 'rgba(80,30,30,0.95)';
      b.style.borderColor = 'rgba(255,90,90,0.65)';
      // Strong glow halo + brighter icon
      b.style.boxShadow = 'inset 0 1px 0 rgba(255,255,255,0.18), 0 0 24px rgba(255,80,80,0.65), 0 2px 12px rgba(0,0,0,0.7)';
      // Show tooltip
      b.style.outline = 'none';
      b._tip = document.createElement('div');
      b._tip.textContent = label;
      b._tip.style.cssText = `
        position: absolute; left: 50%; bottom: 100%;
        transform: translate(-50%, -10px);
        background: rgba(0,0,0,0.85); color: #fff;
        padding: 4px 10px; border-radius: 6px;
        font: 11px system-ui, sans-serif; letter-spacing: 0.05em;
        pointer-events: none; white-space: nowrap;
        border: 1px solid rgba(255,90,90,0.4);
      `;
      b.style.position = 'relative';
      b.appendChild(b._tip);
    });
    b.addEventListener('mouseleave', () => {
      b.style.transform = 'scale(1.0)';
      b.style.background = 'rgba(28,16,16,0.78)';
      b.style.borderColor = 'rgba(255,255,255,0.10)';
      b.style.boxShadow = 'inset 0 1px 0 rgba(255,255,255,0.08), 0 2px 8px rgba(0,0,0,0.6)';
      try { b._tip?.remove(); b._tip = null; } catch {}
    });
    b.addEventListener('click', onClick);
    return b;
  }
  // Fullscreen (circle / record dot icon)
  const tvBtnFull = mkTvBtn('Fullscreen', '<svg width="18" height="18" viewBox="0 0 24 24" fill="#ff5544"><circle cx="12" cy="12" r="9"/></svg>', () => {
    const vid = window.__tvVideo;
    if (!vid) return;
    // Briefly un-hide so the browser will fullscreen the element
    vid.style.position = 'fixed';
    vid.style.inset = '0';
    vid.style.width = '100vw';
    vid.style.height = '100vh';
    vid.style.zIndex = '9999';
    vid.style.display = 'block';
    vid.style.background = '#000';
    vid.controls = true;
    vid.muted = false;
    const exit = () => {
      vid.style.display = 'none';
      vid.style.position = '';
      vid.controls = false;
      document.removeEventListener('fullscreenchange', onFs);
    };
    const onFs = () => { if (!document.fullscreenElement) exit(); };
    document.addEventListener('fullscreenchange', onFs);
    vid.requestFullscreen?.().catch(() => { exit(); });
  });
  // Play (triangle)
