    const header = document.createElement('div');
    header.style.cssText = 'display:flex;justify-content:space-between;opacity:0.85;';
    const lab = document.createElement('span'); lab.textContent = 'Scale (slider)';
    const val = document.createElement('span'); val.style.cssText = 'color:#ffd66b;font:11px ui-monospace,Menlo,monospace;';
    val.textContent = '1.000';
    header.appendChild(lab); header.appendChild(val);
    row.appendChild(header);
    const sl = document.createElement('input');
    sl.type = 'range'; sl.min = '0.30'; sl.max = '3.00'; sl.step = '0.001';
    sl.value = 1;
    sl.style.cssText = 'width:100%;height:18px;';
