      s.quadraticCurveTo( w/2, h/2,  w/2 - rC, h/2);
      s.lineTo(-w/2 + rC, h/2);
      s.quadraticCurveTo(-w/2, h/2, -w/2, h/2 - rC);
      s.lineTo(-w/2, -h/2 + rC);
      s.quadraticCurveTo(-w/2, -h/2, -w/2 + rC, -h/2);
