  window.__macbookCropFront  = _loadMb('macbook.cropFront',  0);
  window.__macbookCropBack   = _loadMb('macbook.cropBack',   0);
  window.__macbookCropTop    = _loadMb('macbook.cropTop',    0);
  window.__macbookCropBottom = _loadMb('macbook.cropBottom', 0);
  window.__macbookOpenAngleSaved  = _loadMb('macbook.openAngleSaved',  0);
  window.__macbookCloseAngleSaved = _loadMb('macbook.closeAngleSaved', -4.36);
  // Each pose also captures the body offset values so the keyboard
  // half can shift between open & close (lets the user nudge things
