  window.__macbookOpenBodyX  = _loadMb('macbook.openBodyX',   0);
  window.__macbookOpenBodyY  = _loadMb('macbook.openBodyY',  -0.020);
  window.__macbookOpenBodyZ  = _loadMb('macbook.openBodyZ',   0.130);
  window.__macbookCloseBodyX = _loadMb('macbook.closeBodyX',  0);
  window.__macbookCloseBodyY = _loadMb('macbook.closeBodyY', -0.266);
  window.__macbookCloseBodyZ = _loadMb('macbook.closeBodyZ', -1.370);
