  _rvbBoxBtn.style.cssText = 'width:100%;padding:6px;margin-top:6px;border:1.5px solid #c33;background:#fff;color:#c33;border-radius:4px;cursor:pointer;font:700 10px ui-monospace;';
  function _paintRvbBoxBtn() { _rvbBoxBtn.textContent = window.__robotBubShowBox ? '🟥 Hide max-size box' : '🟥 Show max-size box'; }
  _rvbBoxBtn.addEventListener('click', () => { window.__robotBubShowBox = !window.__robotBubShowBox; _paintRvbBoxBtn(); });
  _paintRvbBoxBtn();
  _rvbpRows.appendChild(_rvbBoxBtn);

  // ── 🤖 ROBOT TRANSFORM — duplicate of the robot screen panel's
  // X/Y/Z + Scale sliders so the user can reposition the robot
  // directly from this bubble panel. Same window keys + localStorage
  // keys so both panels stay in sync.
  const _robotHeader = document.createElement('div');
  _robotHeader.textContent = '── 🤖 ROBOT POSITION ──';
  _robotHeader.style.cssText = 'font:700 9px ui-monospace;color:#c84300;margin-top:10px;padding-top:8px;border-top:1px solid #ddd;';
  _rvbpRows.appendChild(_robotHeader);
  // Robot X/Y/Z + Scale — uses 3D world units (not pixels).
  function _robotShiftApplier(winKey, persistKey) {
    return (v) => {
      const c = Math.max(-3, Math.min(3, +v));
      window[winKey] = c;
      try {
        const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
        s[persistKey] = c;
        localStorage.setItem('desk-portfolio:positions:v1', JSON.stringify(s));
      } catch {}
      return c;
    };
  }
  function _robot3DRow(label, getVal, apply, opts) {
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;flex-direction:column;gap:3px;';
    const lbl = document.createElement('div');
    lbl.style.cssText = 'display:flex;justify-content:space-between;font-size:9px;';
    const lblText = document.createElement('span'); lblText.textContent = label; lblText.style.fontWeight = '700';
    const valBox = document.createElement('span'); valBox.style.cssText = 'background:#eee;padding:1px 6px;border-radius:3px;';
    lbl.append(lblText, valBox);
    const slider = document.createElement('input');
    slider.type = 'range'; slider.min = opts.min; slider.max = opts.max; slider.step = opts.step;
    slider.value = String(getVal());
    valBox.textContent = (+slider.value).toFixed(2);
    slider.addEventListener('input', () => {
      const c = apply(slider.value);
      valBox.textContent = c.toFixed(2);
    });
    row.append(lbl, slider);
    return row;
  }
  _rvbpRows.appendChild(_robot3DRow('X (− right / + left)',  () => window.__robotShiftX || 0,
    _robotShiftApplier('__robotShiftX', 'robot.shiftX'), { min: -3, max: 3, step: 0.005 }));
  _rvbpRows.appendChild(_robot3DRow('Y (− down / + up)',    () => window.__robotShiftY || 0,
    _robotShiftApplier('__robotShiftY', 'robot.shiftY'), { min: -3, max: 3, step: 0.005 }));
  _rvbpRows.appendChild(_robot3DRow('Z (− in / + out)',     () => window.__robotShiftZ || 0,
    _robotShiftApplier('__robotShiftZ', 'robot.shiftZ'), { min: -3, max: 3, step: 0.005 }));
  _rvbpRows.appendChild(_robot3DRow('Scale ×',              () => window.__robotScaleMult || 1,
    (v) => {
      const c = Math.max(0.2, Math.min(3, +v));
      window.__robotScaleMult = c;
      try {
        const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
        s['robot.scaleMult'] = c;
        localStorage.setItem('desk-portfolio:positions:v1', JSON.stringify(s));
      } catch {}
      return c;
    }, { min: 0.2, max: 3, step: 0.005 }));

  // ── 🌀 ROBOT ROTATION — overlay onto the centered pose. Binds to
  // the SAME window keys + localStorage keys as the robot screen
  // panel's Face X/Y/Z sliders so both stay in sync.
  const _rotHeader = document.createElement('div');
  _rotHeader.textContent = '── 🌀 ROBOT ROTATION ──';
  _rotHeader.style.cssText = 'font:700 9px ui-monospace;color:#c84300;margin-top:8px;padding-top:6px;border-top:1px solid #eee;';
  _rvbpRows.appendChild(_rotHeader);
  function _robotRotApplier(winKey, persistKey) {
    return (v) => {
      const c = Math.max(-Math.PI, Math.min(Math.PI, +v));
      window[winKey] = c;
      try {
        const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
        s[persistKey] = c;
        localStorage.setItem('desk-portfolio:positions:v1', JSON.stringify(s));
      } catch {}
      return c;
    };
  }
  _rvbpRows.appendChild(_robot3DRow('Rot X (tilt fwd / back)',     () => window.__robotFaceX || 0,
    _robotRotApplier('__robotFaceX', 'robot.faceX'), { min: -Math.PI, max: Math.PI, step: 0.01 }));
  _rvbpRows.appendChild(_robot3DRow('Rot Y (turn left / right)',   () => window.__robotFaceY || 0,
    _robotRotApplier('__robotFaceY', 'robot.faceY'), { min: -Math.PI, max: Math.PI, step: 0.01 }));
  _rvbpRows.appendChild(_robot3DRow('Rot Z (roll)',                () => window.__robotFaceZ || 0,
    _robotRotApplier('__robotFaceZ', 'robot.faceZ'), { min: -Math.PI, max: Math.PI, step: 0.01 }));

  // ── 💃 ROBOT MODE — TALK / CHILL / OFF buttons drive the rig
  // animator. AUTO = drive from bubble typewriter state. Manual
  // selection sticks until user clicks AUTO again.
  const _modeHeader = document.createElement('div');
  _modeHeader.textContent = '── 💃 ANIMATION MODE ──';
  _modeHeader.style.cssText = 'font:700 9px ui-monospace;color:#c84300;margin-top:8px;padding-top:6px;border-top:1px solid #eee;';
  _rvbpRows.appendChild(_modeHeader);
  const _modeRow = document.createElement('div');
  _modeRow.style.cssText = 'display:flex;gap:4px;';
  function _mkModeBtn(label, mode) {
    const b = document.createElement('button');
    b.type = 'button';
    b.textContent = label;
    b.dataset.mode = mode;
    b.style.cssText = 'flex:1;padding:5px 6px;border-radius:6px;border:1.5px solid #1a1a1a;background:#fff;color:#1a1a1a;cursor:pointer;font:700 10px ui-monospace;';
    b.addEventListener('click', () => {
      // 🔓 Force inspect mode OFF — animator gate ignores everything
      // if inspect mode is on. User clicking a mode button = unambiguous
      // intent to animate.
      if (window.__inspectMode) {
        window.__inspectMode = false;
        if (typeof _paintInspBtn === 'function') _paintInspBtn();
        if (typeof _restoreAll === 'function') _restoreAll();
      }
      // 🔄 Clear baseRot cache so animations recapture fresh rest pose
      // on the next frame — prevents stale-cache "stuck pose" feel.
      window.__robotBaseRotCache = {};
      if (mode === 'auto') {
        window.__robotRigModeManual = null;
      } else {
        window.__robotRigModeManual = mode;
        window.__robotRigMode = mode;
      }
      console.log(`[robot-mode] → ${mode}`);
      _paintRobotModeBtns();
    });
    return b;
  }
  const _bChill = _mkModeBtn('🛌 CHILL', 'chill');
  const _bTalk  = _mkModeBtn('🗣 TALK',  'talk');
  const _bOff   = _mkModeBtn('⏹ OFF',   'off');
  const _bAuto  = _mkModeBtn('🤖 AUTO',  'auto');
  // Local name (not _paintModeBtns — that name is taken by the kevin
  // panel earlier in this scope; with hoisting, two function decls
  // collide and break the kevin one's TDZ access).
  const _paintRobotModeBtns = () => {
    [_bChill, _bTalk, _bOff, _bAuto].forEach((b) => {
      const cur = window.__robotRigModeManual || 'auto';
      const on = b.dataset.mode === cur;
      b.style.background = on ? '#c84300' : '#fff';
      b.style.color      = on ? '#fff'    : '#1a1a1a';
      b.style.borderColor = on ? '#c84300' : '#1a1a1a';
    });
  };
  _modeRow.append(_bAuto, _bChill, _bTalk, _bOff);
  _rvbpRows.appendChild(_modeRow);
  _paintRobotModeBtns();

  // Convert a preset's `hinges` object (role → axisCfg) into the new
  // animator's array format (`[{ role, x, y, z }, ...]`). Frequencies
  // in the old presets are RAD/SEC; new animator uses HZ. Convert.
  function _presetToSpec(preset) {
    if (!preset || !preset.hinges) return [];
    const spec = [];
    const convAxis = (axis) => {
      if (!axis) return undefined;
      const freqHz = (axis.freq || 0) / (2 * Math.PI);
      return { off: axis.off || 0, freq: freqHz, amp: axis.amp || 0, phase: axis.phase || 0 };
    };
    Object.keys(preset.hinges).forEach((role) => {
      // Skip head — user wants head to never shake.
      if (role === 'head' || role === 'body.head') return;
      const cfg = preset.hinges[role];
      spec.push({ role, x: convAxis(cfg.x), y: convAxis(cfg.y), z: convAxis(cfg.z) });
    });
    return spec;
  }

  // (Removed: old CHILL PRESETS + TALK PRESETS grids — they were the
  // legacy 10×10 preset buttons that swapped __ROBOT_CHILL_SPEC and
  // __ROBOT_TALK_SPEC. The v3 animator uses TALK_FNS/CHILL_FNS directly
  // and ignores those specs, so the 20 buttons were "wires crossed" UI
  // doing nothing visible. Use ⚡ QUICK STYLES + 🎬 NAMED PRESETS
  // below the ANIMATION KNOBS section instead.)
  function _paintPresetBtns() { /* no-op — kept for backwards compat */ }

  // ── 🔧 HINGE MAPPER — manual assignment of GLB nodes to roles.
  // The regex auto-discovery rarely catches every arm hinge; this UI
  // lets the user pick from a dropdown of all loaded mesh names.
  // Mapping persists to localStorage and is re-applied on every load.
  const _mapHdr = document.createElement('div');
  _mapHdr.textContent = '── 🔧 HINGE MAPPER ──';
  _mapHdr.style.cssText = 'font:700 9px ui-monospace;color:#c84300;margin-top:8px;padding-top:6px;border-top:1px solid #eee;';
  _rvbpRows.appendChild(_mapHdr);
  const _mapNote = document.createElement('div');
  _mapNote.style.cssText = 'font:600 8px ui-monospace;color:#666;margin-bottom:4px;';
  _mapNote.textContent = 'Pick which GLB mesh is each joint:';
  _rvbpRows.appendChild(_mapNote);
  const _hingeRoles = ['body.base','body.head','leftArm.shoulder','leftArm.elbow','leftArm.wrist','rightArm.shoulder','rightArm.elbow','rightArm.wrist'];
  const _mapperRows = {};
  _hingeRoles.forEach((role) => {
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;gap:4px;align-items:center;margin-bottom:2px;';
    const lbl = document.createElement('span');
    lbl.textContent = role;
    lbl.style.cssText = 'flex:0 0 110px;font:600 9px ui-monospace;color:#1a1a1a;';
    const sel = document.createElement('select');
    sel.style.cssText = 'flex:1;font:600 9px ui-monospace;padding:2px;border:1px solid #999;border-radius:3px;background:#fff;';
    sel.addEventListener('change', () => {
      const meshName = sel.value;
      const idx = window.__robotMeshIndex || {};
      const obj = idx[meshName];
      if (!window.__robotHingeMap) window.__robotHingeMap = {};
      if (obj) {
        window.__robotHingeMap[role] = {
          obj,
          baseRot: { x: obj.rotation.x, y: obj.rotation.y, z: obj.rotation.z },
          name: meshName,
        };
        console.log(`[robot-rig] MAPPED ${role} → "${meshName}"`);
      } else {
        delete window.__robotHingeMap[role];
      }
      // Persist
      try {
        const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
        s['robot.hingeMap'] = s['robot.hingeMap'] || {};
        if (meshName) s['robot.hingeMap'][role] = meshName;
        else delete s['robot.hingeMap'][role];
        localStorage.setItem('desk-portfolio:positions:v1', JSON.stringify(s));
      } catch {}
    });
    row.append(lbl, sel);
    _rvbpRows.appendChild(row);
    _mapperRows[role] = sel;
  });
  // 🧪 TEST button — pulses each mapped hinge in sequence so the user
  // can verify which mesh is which.
  const _testBtn = document.createElement('button');
  _testBtn.type = 'button';
  _testBtn.textContent = '🧪 TEST hinges';
  _testBtn.style.cssText = 'width:100%;padding:6px;margin-top:4px;border:1.5px solid #c84300;background:#fff;color:#c84300;border-radius:4px;cursor:pointer;font:700 10px ui-monospace;';
  _testBtn.addEventListener('click', () => {
    const map = window.__robotHingeMap || {};
    const roles = Object.keys(map);
    if (!roles.length) { console.warn('[robot-rig] no hinges to test'); return; }
    window.__robotRigModeManual = 'off';
    window.__robotRigMode = 'off';
    _paintRobotModeBtns();
    let i = 0;
    const step = () => {
      if (i >= roles.length) { window.__robotRigModeManual = null; return; }
      const role = roles[i];
      const h = map[role];
      if (h && h.obj) {
        const orig = { x: h.obj.rotation.x, y: h.obj.rotation.y, z: h.obj.rotation.z };
        // Pulse: +0.5 rad on each axis for 250ms, then restore.
        h.obj.rotation.x = (h.baseRot?.x || 0) + 0.5;
        h.obj.rotation.y = (h.baseRot?.y || 0) + 0.3;
        h.obj.rotation.z = (h.baseRot?.z || 0) + 0.5;
        console.log(`[robot-rig] 🧪 PULSING ${role} → "${h.name}"`);
        setTimeout(() => {
          h.obj.rotation.x = orig.x;
          h.obj.rotation.y = orig.y;
          h.obj.rotation.z = orig.z;
          i++;
          setTimeout(step, 200);
        }, 450);
      } else {
        i++; setTimeout(step, 50);
      }
    };
    step();
  });
  _rvbpRows.appendChild(_testBtn);
  // Repaint function — populates dropdowns once GLB nodes are loaded.
  window.__robotHingeMapperRepaint = () => {
    const names = Object.keys(window.__robotMeshIndex || {});
    if (!names.length) return;
    const persisted = (() => {
      try {
        const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
        return s['robot.hingeMap'] || {};
      } catch { return {}; }
    })();
    _hingeRoles.forEach((role) => {
      const sel = _mapperRows[role];
      if (!sel) return;
      sel.innerHTML = '';
      const empty = document.createElement('option');
      empty.value = ''; empty.textContent = '— none —';
      sel.appendChild(empty);
      names.forEach((n) => {
        const opt = document.createElement('option');
        opt.value = n; opt.textContent = n;
        sel.appendChild(opt);
      });
      // Pre-select: persisted manual mapping > current auto-discovery > none
      const cur = (persisted[role]) || (window.__robotHingeMap?.[role]?.name) || '';
      sel.value = cur;
    });
  };
  // Repaint immediately in case the GLB already loaded by the time the
  // panel is built (subsequent picks of robot menu item).
  window.__robotHingeMapperRepaint();
  // Intensity slider for the rig
  _rvbpRows.appendChild(_robot3DRow('Rig Intensity',  () => window.__robotRigIntensity ?? 1,
    (v) => {
      const c = Math.max(0, Math.min(2, +v));
      window.__robotRigIntensity = c;
      try {
        const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
        s['robot.rig.intensity'] = c;
        localStorage.setItem('desk-portfolio:positions:v1', JSON.stringify(s));
      } catch {}
      return c;
    }, { min: 0, max: 2, step: 0.05 }));

  // ── 🎚️ PER-GROUP INTENSITY + SPEED SLIDERS ──
  const _animHdr = document.createElement('div');
  _animHdr.textContent = '── 🎚️ ANIMATION KNOBS ──';
  _animHdr.style.cssText = 'font:700 9px ui-monospace;color:#c84300;margin-top:8px;padding-top:6px;border-top:1px solid #eee;';
  _rvbpRows.appendChild(_animHdr);
  // Quick MODE COMPARE buttons — duplicate of the top mode buttons so
  // the user can switch modes without scrolling back up while tweaking
  // amplitude sliders.
  const _quickModeRow = document.createElement('div');
  _quickModeRow.style.cssText = 'display:flex;gap:4px;margin-bottom:6px;';
  function _mkQuickModeBtn(label, mode) {
    const b = document.createElement('button');
    b.type = 'button';
    b.textContent = label;
    b.dataset.mode = mode;
    b.style.cssText = 'flex:1;padding:5px 6px;border-radius:5px;border:1.5px solid #1a1a1a;background:#fff;color:#1a1a1a;cursor:pointer;font:700 10px ui-monospace;';
    b.addEventListener('click', () => {
      if (window.__inspectMode) {
        window.__inspectMode = false;
        if (typeof _paintInspBtn === 'function') _paintInspBtn();
        if (typeof _restoreAll === 'function') _restoreAll();
      }
      window.__robotBaseRotCache = {};
      if (mode === 'auto') {
        window.__robotRigModeManual = null;
      } else {
        window.__robotRigModeManual = mode;
        window.__robotRigMode = mode;
      }
      _paintQuickModeBtns();
      if (typeof _paintRobotModeBtns === 'function') _paintRobotModeBtns();
    });
    return b;
  }
  const _qAuto  = _mkQuickModeBtn('🤖 AUTO',  'auto');
  const _qChill = _mkQuickModeBtn('🛌 CHILL', 'chill');
  const _qTalk  = _mkQuickModeBtn('🗣 TALK',  'talk');
  const _qOff   = _mkQuickModeBtn('⏹ OFF',   'off');
  function _paintQuickModeBtns() {
    [_qAuto, _qChill, _qTalk, _qOff].forEach((b) => {
      const cur = window.__robotRigModeManual || 'auto';
      const on = b.dataset.mode === cur;
      b.style.background = on ? '#c84300' : '#fff';
      b.style.color      = on ? '#fff'    : '#1a1a1a';
      b.style.borderColor = on ? '#c84300' : '#1a1a1a';
    });
  }
  _quickModeRow.append(_qAuto, _qChill, _qTalk, _qOff);
  _rvbpRows.appendChild(_quickModeRow);
  _paintQuickModeBtns();

  // ── 🧠 MODE-AWARE PRESETS — the global knobs below (arm/body/head/
  // hand/speed) auto-save under per-mode keys (talk vs chill). Clicking
  // a mode button restores the saved values for that mode.
  const _modeAwareSliders = {};   // winKey → { slider, valBox, persistBase, fallback }
  function _curRigMode() {
    const m = window.__robotRigModeManual || 'auto';
    if (m === 'auto') return window.__robotRigMode || 'chill';
    return m;
  }
  function _modeAwareApplier(winKey, persistBase, min, max) {
    return (v) => {
      const c = Math.max(min, Math.min(max, +v));
      window[winKey] = c;
      const mode = _curRigMode();
      try {
        const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
        s[`${persistBase}.${mode}`] = c;
        localStorage.setItem('desk-portfolio:positions:v1', JSON.stringify(s));
      } catch {}
      return c;
    };
  }
  // Expose globally so the per-frame animator can call this when AUTO
  // mode flips between TALK and CHILL (bubble typing state changed)
  window.__refreshRobotModeAwareSliders = () => _refreshModeAwareSliders();
  function _refreshModeAwareSliders() {
    const mode = _curRigMode();
    let s = {};
    try { s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}'); } catch {}
    Object.keys(_modeAwareSliders).forEach((winKey) => {
      const e = _modeAwareSliders[winKey];
      const k = `${e.persistBase}.${mode}`;
      const v = (typeof s[k] === 'number') ? s[k] : (e.fallback ?? 1);
      window[winKey] = v;
      e.slider.value = String(v);
      e.valBox.textContent = (+v).toFixed(2);
    });
  }
  // Build a mode-aware slider row (input range + auto-saving + registry).
  function _modeAwareRow(label, winKey, persistBase, min, max, step, fallback) {
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;flex-direction:column;gap:3px;';
    const lbl = document.createElement('div');
    lbl.style.cssText = 'display:flex;justify-content:space-between;font-size:9px;';
    const lblText = document.createElement('span'); lblText.textContent = label; lblText.style.fontWeight = '700';
    const valBox = document.createElement('span'); valBox.style.cssText = 'background:#eee;padding:1px 6px;border-radius:3px;';
    lbl.append(lblText, valBox);
    const slider = document.createElement('input');
    slider.type = 'range'; slider.min = min; slider.max = max; slider.step = step;
    // On first load, prefer saved value for current mode, then live var, then fallback
    let s = {};
    try { s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}'); } catch {}
    const mode = _curRigMode();
    const savedV = s[`${persistBase}.${mode}`];
    const initV = (typeof savedV === 'number') ? savedV : (typeof window[winKey] === 'number' ? window[winKey] : (fallback ?? 1));
    window[winKey] = initV;
    slider.value = String(initV);
    valBox.textContent = (+slider.value).toFixed(2);
    slider.addEventListener('input', () => {
      const c = _modeAwareApplier(winKey, persistBase, min, max)(slider.value);
      valBox.textContent = c.toFixed(2);
    });
    row.append(lbl, slider);
    _modeAwareSliders[winKey] = { slider, valBox, persistBase, fallback };
    return row;
  }
  // Hook BOTH mode-button rows (top + quick) to refresh after any switch
  [_bChill, _bTalk, _bOff, _bAuto, _qChill, _qTalk, _qOff, _qAuto].forEach((btn) => {
    if (!btn) return;
    btn.addEventListener('click', () => { setTimeout(_refreshModeAwareSliders, 0); });
  });

  function _robotKnobApplier(winKey, persistKey, min, max) {
    return (v) => {
      const c = Math.max(min, Math.min(max, +v));
      window[winKey] = c;
      try {
        const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
        s[persistKey] = c;
        localStorage.setItem('desk-portfolio:positions:v1', JSON.stringify(s));
      } catch {}
      return c;
    };
  }
  // Load persisted values once
  try {
    const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
    if (typeof s['robot.arm.intensity']  === 'number') window.__robotArmIntensity  = s['robot.arm.intensity'];
    if (typeof s['robot.body.intensity'] === 'number') window.__robotBodyIntensity = s['robot.body.intensity'];
    if (typeof s['robot.head.intensity'] === 'number') window.__robotHeadIntensity = s['robot.head.intensity'];
    if (typeof s['robot.hand.intensity'] === 'number') window.__robotHandIntensity = s['robot.hand.intensity'];
    if (typeof s['robot.anim.speed']     === 'number') window.__robotAnimSpeed     = s['robot.anim.speed'];
  } catch {}
  // Mode-aware: each slider auto-saves under a per-mode key (.talk / .chill)
  // and refreshes when a mode button is clicked.
  _rvbpRows.appendChild(_modeAwareRow('💪 Arm intensity',  '__robotArmIntensity',  'robot.arm.intensity',  0,   3, 0.05, 1));
  _rvbpRows.appendChild(_modeAwareRow('🦴 Body intensity', '__robotBodyIntensity', 'robot.body.intensity', 0,   3, 0.05, 1));
  _rvbpRows.appendChild(_modeAwareRow('🤖 Head intensity', '__robotHeadIntensity', 'robot.head.intensity', 0,   3, 0.05, 1));
