    btn.title = style.desc;
    btn.style.cssText = 'padding:5px 6px;border-radius:5px;border:1px solid #1a1a1a;background:#fff;color:#1a1a1a;cursor:pointer;font:700 9px ui-monospace;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;';
    btn.addEventListener('click', () => {
      const mode = _curRigMode();
      // Apply the snapshot — save each value to the CURRENT mode's key
      Object.keys(style.snap).forEach((winKey) => {
        const v = style.snap[winKey];
        window[winKey] = v;
        // Persist to mode-aware key if this slider is registered as mode-aware
        const entry = _modeAwareSliders[winKey];
        if (entry) {
          try {
            const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
            s[`${entry.persistBase}.${mode}`] = v;
            localStorage.setItem('desk-portfolio:positions:v1', JSON.stringify(s));
          } catch {}
        }
      });
      window.__robotBaseRotCache = {};
      if (typeof _refreshModeAwareSliders === 'function') _refreshModeAwareSliders();
      // Visual flash
      btn.style.background = '#c84300';
      btn.style.color = '#fff';
      setTimeout(() => { btn.style.background = '#fff'; btn.style.color = '#1a1a1a'; }, 400);
      console.log(`[robot-style] applied "${style.name}" for mode=${mode}`);
    });
    _styleGrid.appendChild(btn);
