  _screenRows.appendChild(_panelFontGrid);

  // ── COLOR SCHEME picker for the monitor's canvas display ──────
  _addScreenPanelHeader('Color scheme');
  const _SCHEME_NAMES = [
    'CRT Green', 'Amber CRT', 'Cyan', 'Paper',
    'Mono White', 'Hot Pink', 'Indigo', 'Sepia',
  ];
  const _schemeGrid = document.createElement('div');
  _schemeGrid.style.cssText = 'display:grid;grid-template-columns:1fr 1fr;gap:4px;margin:4px 0;';
