  // ── Custom per-element COLOR pickers (DISABLED — brand schemes
  // handle this automatically). Keep the helpers in code, but
  // don't render the header / pickers.
  // _addScreenPanelHeader('Custom colors');
  function _hex2rgba(hex, alpha = 1) {
    const m = /^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(hex);
    if (!m) return null;
    const r = parseInt(m[1], 16), g = parseInt(m[2], 16), b = parseInt(m[3], 16);
    return `rgba(${r},${g},${b},${alpha})`;
  }
  // Restore persisted custom-color picks at boot
  try {
    const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
    const sm = window.__tvSideMonState;
    if (sm?._scrContent) {
      sm._scrContent._customColors = sm._scrContent._customColors || {};
      ['bg','label','bright','dim','active','btnStroke','btnFill'].forEach((k) => {
        const v = s['tv.sidemon.color.' + k];
        if (typeof v === 'string') sm._scrContent._customColors[k] = v;
      });
    }
  } catch {}
  function _mkColorRow(label, key, defaultHex, alpha) {
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;align-items:center;gap:8px;margin:3px 0;';
    const lab = document.createElement('span');
    lab.textContent = label;
    lab.style.cssText = 'flex:1;font-size:11px;opacity:0.85;';
    const colorInput = document.createElement('input');
    colorInput.type = 'color';
    colorInput.style.cssText = 'width:40px;height:24px;border-radius:4px;border:1px solid rgba(255,255,255,0.15);background:transparent;cursor:pointer;padding:0;';
    // Load persisted value if present
    try {
      const s = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
      colorInput.value = s['tv.sidemon.color.' + key + '.hex'] || defaultHex;
    } catch { colorInput.value = defaultHex; }
    const clearBtn = document.createElement('button');
    clearBtn.textContent = '✕';
    clearBtn.title = 'Reset to scheme color';
    clearBtn.style.cssText = 'width:24px;height:24px;border-radius:4px;border:1px solid rgba(255,255,255,0.15);background:transparent;color:#fff;cursor:pointer;font-size:10px;padding:0;';
    colorInput.addEventListener('input', () => {
      const hex = colorInput.value;
      const rgba = _hex2rgba(hex, alpha);
      try {
        const sm = window.__tvSideMonState;
        if (sm?._scrContent) {
          sm._scrContent._customColors = sm._scrContent._customColors || {};
          sm._scrContent._customColors[key] = rgba;
          sm._scrRedraw?.();
        }
      } catch {}
      try {
        const st = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
        st['tv.sidemon.color.' + key]       = rgba;
        st['tv.sidemon.color.' + key + '.hex'] = hex;
        localStorage.setItem('desk-portfolio:positions:v1', JSON.stringify(st));
      } catch {}
    });
    clearBtn.addEventListener('click', () => {
      try {
        const sm = window.__tvSideMonState;
        if (sm?._scrContent?._customColors) {
          delete sm._scrContent._customColors[key];
          sm._scrRedraw?.();
        }
      } catch {}
      try {
        const st = JSON.parse(localStorage.getItem('desk-portfolio:positions:v1') || '{}');
        delete st['tv.sidemon.color.' + key];
        delete st['tv.sidemon.color.' + key + '.hex'];
        localStorage.setItem('desk-portfolio:positions:v1', JSON.stringify(st));
      } catch {}
    });
    row.appendChild(lab); row.appendChild(colorInput); row.appendChild(clearBtn);
    _screenRows.appendChild(row);
  }
  // Custom color rows are intentionally NOT added — brand schemes
  // do the per-client coloring automatically. Keeping _mkColorRow
  // and the persistence path in code in case we want them back.
