              const _st   = window.__tedxVidState;
              const _vMat = window.__tedxVidMat;
              if (_v) { _v.pause(); _v.muted = true; _v.volume = 0; _v.currentTime = 0; }
              if (_st) { _st.playing = false; _st.clickedAt = 0; _st.fadeStart = 0; }
